//! OS randomness for local session capabilities. Never print generated bytes.
//! Also included by the launcher; this file deliberately depends only on getrandom.
pub fn bytes<const N: usize>() -> Result<[u8; N], &'static str> {
    if N != 16 && N != 32 { return Err("unsupported session random length"); }
    let mut bytes = [0u8; N];
    getrandom::fill(&mut bytes).map_err(|_| "OS session randomness unavailable")?;
    if bytes.iter().all(|value| *value == 0) { return Err("OS session randomness returned an invalid capability"); }
    Ok(bytes)
}
